#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
using namespace std;

int main(){
    double varianceA=0.04,varianceB=0.01,covariance=0.005;
    double denominator=varianceA+varianceB-2*covariance;
    double w=(varianceB-covariance)/denominator;
    w=max(0.0,min(1.0,w));
    double risk=w*w*varianceA+(1-w)*(1-w)*varianceB+2*w*(1-w)*covariance;
    cout<<w<<" "<<risk<<"\n";
    return 0;
}
